-- ROOT10 EXACT SINGLE-WINDOW ACTIVATION. One transaction; fail closed; no GA issuance.
begin;
set local lock_timeout='5s'; set local statement_timeout='60s';
do $pre$
declare h clued_control.current_head; c clued_control.execution_current; d text;
begin
 select * into h from clued_control.current_head where root_id='ctr_414bd3c724264a83894b0c55cf2ab878' for update;
 select * into c from clued_control.execution_current where root_id='ctr_414bd3c724264a83894b0c55cf2ab878' for update;
 lock table clued_control.successor_binding in access exclusive mode;
 if h.sequence<>11 or h.generation_id<>'ctrgen_c725e90a595c00a041754ede3b00f408' or h.revoked or c.sequence<>138 or c.active_ga_id is not null or c.pending_budget_sequence is not null
 or c.charged_seconds<>12306 or c.charged_evidence_bytes<>2738465715
 or (select count(*) from clued_control.events where root_id=h.root_id)<>11 or (select count(*) from clued_control.execution_events where root_id=h.root_id)<>138
 or (select count(*) from clued_control.gate_attempts where root_id=h.root_id)<>18
 or not exists(select 1 from clued_control.gate_attempts where root_id=h.root_id and ga_id='ga_6addc4f9764b69ba8c10d258135ae0d4' and ga_sha256='327bb92ca8a27f8e67eac06daaa27afa5df99814823fe0a2eb69b7c41747641a' and phase='BLOCKED' and budget_sequence=102 and container_id is null and receipt_sha256='3d6fc55e6d2065fb40974161f3c0abb556817989c560e3072a080bea033ccfdd')
 then raise exception 'ROOT12_ACTIVATION_STALE_PREIMAGE'; end if;
 select pg_get_constraintdef(oid,false) into d from pg_constraint where conrelid='clued_control.successor_binding'::regclass and conname='successor_binding_budget_sequence_floor_check'; if d is distinct from 'CHECK (((budget_sequence_floor = 98) OR ((generation_id = ''ctrgen_48100437d24e448ba01c542ebe1290da''::text) AND (budget_sequence_floor = 117)) OR ((generation_id = ''ctrgen_c725e90a595c00a041754ede3b00f408''::text) AND (budget_sequence_floor = 136))))' then raise exception 'successor floor constraint changed'; end if;
 select pg_get_constraintdef(oid,false) into d from pg_constraint where conrelid='clued_control.successor_binding'::regclass and conname='successor_binding_predecessor_generation_id_check'; if d is distinct from 'CHECK (((predecessor_generation_id = ''ctrgen_26769cc7109ced40bc4016b2af678198''::text) OR ((generation_id = ''ctrgen_308a1dfc185cff633892638581e0a34c''::text) AND (predecessor_generation_id = ''ctrgen_b060bc520329398936e461af6a477f94''::text)) OR ((generation_id = ''ctrgen_48100437d24e448ba01c542ebe1290da''::text) AND (predecessor_generation_id = ''ctrgen_308a1dfc185cff633892638581e0a34c''::text)) OR ((generation_id = ''ctrgen_c725e90a595c00a041754ede3b00f408''::text) AND (predecessor_generation_id = ''ctrgen_48100437d24e448ba01c542ebe1290da''::text))))' then raise exception 'successor predecessor constraint changed'; end if;
 select pg_get_constraintdef(oid,false) into d from pg_constraint where conrelid='clued_control.execution_current'::regclass and conname='execution_current_charged_seconds_check'; if d is distinct from 'CHECK (((charged_seconds >= 1410) AND (charged_seconds <= 12306)))' then raise exception 'seconds cap constraint changed'; end if;
 select pg_get_constraintdef(oid,false) into d from pg_constraint where conrelid='clued_control.execution_current'::regclass and conname='execution_current_charged_evidence_bytes_check'; if d is distinct from 'CHECK (((charged_evidence_bytes >= 19264968) AND (charged_evidence_bytes <= ''2738465715''::bigint)))' then raise exception 'evidence cap constraint changed'; end if;
 
 select encode(sha256(convert_to(pg_get_functiondef(to_regprocedure('clued_control.read_root(text)')),'UTF8')),'hex') into d;
 if d is distinct from 'e17a317a9dce6b6b947b55267f62a20af4b6bef6a9a68f808d53c572324cbfba' then raise exception 'critical function changed: read_root'; end if;
 if not exists(select 1 from pg_proc p where p.oid=to_regprocedure('clued_control.read_root(text)') and p.proowner='postgres'::regrole and p.prosecdef
   and p.provolatile='s' and p.proconfig @> array['search_path=""','TimeZone=UTC']::text[]
   and p.proacl::text='{postgres=X/postgres,service_role=X/postgres}')
 then raise exception 'critical function security changed: read_root'; end if;
 select encode(sha256(convert_to(pg_get_functiondef(to_regprocedure('clued_control.reserve_execution_budget(text,text)')),'UTF8')),'hex') into d;
 if d is distinct from '636659c25f591a645a0aae7451030b8688e91bc994cafb9e0fb8f18e155a6d3d' then raise exception 'critical function changed: reserve_execution_budget'; end if;
 if not exists(select 1 from pg_proc p where p.oid=to_regprocedure('clued_control.reserve_execution_budget(text,text)') and p.proowner='postgres'::regrole and p.prosecdef
   and p.provolatile='v' and p.proconfig @> array['search_path=""','TimeZone=UTC']::text[]
   and p.proacl::text='{postgres=X/postgres,service_role=X/postgres}')
 then raise exception 'critical function security changed: reserve_execution_budget'; end if;
 select encode(sha256(convert_to(pg_get_functiondef(to_regprocedure('clued_control.reserve_gate(text,text)')),'UTF8')),'hex') into d;
 if d is distinct from 'c5e237c63c4b8272343d747ba758b9be159bd1b0daf0f56cbc494dadc61e73da' then raise exception 'critical function changed: reserve_gate'; end if;
 if not exists(select 1 from pg_proc p where p.oid=to_regprocedure('clued_control.reserve_gate(text,text)') and p.proowner='postgres'::regrole and p.prosecdef
   and p.provolatile='v' and p.proconfig @> array['search_path=""','TimeZone=UTC']::text[]
   and p.proacl::text='{postgres=X/postgres,service_role=X/postgres}')
 then raise exception 'critical function security changed: reserve_gate'; end if;
 select encode(sha256(convert_to(pg_get_functiondef(to_regprocedure('clued_control.append_status_manifest(text,text)')),'UTF8')),'hex') into d;
 if d is distinct from '1a75b3b9ecfec1d2fe5c700124544d323506fa16e35a99be7c1dc5c3c1ec6280' then raise exception 'critical function changed: append_status_manifest'; end if;
 if not exists(select 1 from pg_proc p where p.oid=to_regprocedure('clued_control.append_status_manifest(text,text)') and p.proowner='postgres'::regrole and p.prosecdef
   and p.provolatile='v' and p.proconfig @> array['search_path=""','TimeZone=UTC']::text[]
   and p.proacl::text='{postgres=X/postgres,service_role=X/postgres}')
 then raise exception 'critical function security changed: append_status_manifest'; end if;
 select encode(sha256(convert_to(pg_get_functiondef(to_regprocedure('clued_control.transition_successor_binding(jsonb)')),'UTF8')),'hex') into d;
 if d is distinct from '2d398f53984e319bb1006e8e00b70c7520c427da25bddb8b43b918b9c12404cf' then raise exception 'critical function changed: transition_successor_binding'; end if;
 if not exists(select 1 from pg_proc p where p.oid=to_regprocedure('clued_control.transition_successor_binding(jsonb)') and p.proowner='postgres'::regrole and p.prosecdef
   and p.provolatile='v' and p.proconfig @> array['search_path=""','TimeZone=UTC']::text[]
   and p.proacl::text='{postgres=X/postgres,service_role=X/postgres}')
 then raise exception 'critical function security changed: transition_successor_binding'; end if;
 select encode(sha256(convert_to(pg_get_functiondef(to_regprocedure('clued_control.effective_execution_binding()')),'UTF8')),'hex') into d;
 if d is distinct from '9b5f160a059fc31719202c540557ff45d4ba8b1f2d05373d7a79b10abd566370' then raise exception 'critical function changed: effective_execution_binding'; end if;
 if not exists(select 1 from pg_proc p where p.oid=to_regprocedure('clued_control.effective_execution_binding()') and p.proowner='postgres'::regrole and p.prosecdef
   and p.provolatile='s' and p.proconfig @> array['search_path=""','TimeZone=UTC']::text[]
   and p.proacl::text='{postgres=X/postgres}')
 then raise exception 'critical function security changed: effective_execution_binding'; end if;
 select encode(sha256(convert_to(pg_get_functiondef(to_regprocedure('clued_control.effective_execution_window()')),'UTF8')),'hex') into d;
 if d is distinct from 'c1531b643ae7ac19079def01664133b236e35b1ba47c10b5a14c321f7131c09f' then raise exception 'critical function changed: effective_execution_window'; end if;
 if not exists(select 1 from pg_proc p where p.oid=to_regprocedure('clued_control.effective_execution_window()') and p.proowner='postgres'::regrole and p.prosecdef
   and p.provolatile='s' and p.proconfig @> array['search_path=""','TimeZone=UTC']::text[]
   and p.proacl::text='{postgres=X/postgres,service_role=X/postgres}')
 then raise exception 'critical function security changed: effective_execution_window'; end if;
end $pre$;

alter table clued_control.successor_binding drop constraint successor_binding_budget_sequence_floor_check,
 add constraint successor_binding_budget_sequence_floor_check check (budget_sequence_floor=98
   or (generation_id='ctrgen_48100437d24e448ba01c542ebe1290da' and budget_sequence_floor=117)
   or (generation_id='ctrgen_c725e90a595c00a041754ede3b00f408' and budget_sequence_floor=136)
   or (generation_id='ctrgen_1cf79ef9a7ccc37800e8837ac8c10287' and budget_sequence_floor=143));
alter table clued_control.successor_binding drop constraint successor_binding_predecessor_generation_id_check,
 add constraint successor_binding_predecessor_generation_id_check check (
 predecessor_generation_id='ctrgen_26769cc7109ced40bc4016b2af678198' or
 (generation_id='ctrgen_308a1dfc185cff633892638581e0a34c' and predecessor_generation_id='ctrgen_b060bc520329398936e461af6a477f94') or
 (generation_id='ctrgen_48100437d24e448ba01c542ebe1290da' and predecessor_generation_id='ctrgen_308a1dfc185cff633892638581e0a34c') or
 (generation_id='ctrgen_c725e90a595c00a041754ede3b00f408' and predecessor_generation_id='ctrgen_48100437d24e448ba01c542ebe1290da') or
 (generation_id='ctrgen_1cf79ef9a7ccc37800e8837ac8c10287' and predecessor_generation_id='ctrgen_c725e90a595c00a041754ede3b00f408'));
alter table clued_control.execution_current drop constraint "execution_current_charged_seconds_check",
 add constraint "execution_current_charged_seconds_check" CHECK (((charged_seconds >= 1410) AND (charged_seconds <= 12906)));
alter table clued_control.execution_current drop constraint "execution_current_charged_evidence_bytes_check",
 add constraint "execution_current_charged_evidence_bytes_check" CHECK (((charged_evidence_bytes >= 19264968) AND (charged_evidence_bytes <= '2872683443'::bigint)));

CREATE OR REPLACE FUNCTION clued_control.read_root(p_root_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
with x as (
 select a binding,h.sequence,h.generation_id,h.revoked,e.request->'body' generation_body,
        s.binding_id successor_binding_id,s.binding_sha256 successor_binding_sha256,
        s.not_before successor_not_before,s.expires_at successor_expires_at,
        se.sequence successor_registration_sequence
 from clued_control.accepted_binding a
 left join clued_control.current_head h using(root_id)
 left join clued_control.events e on e.root_id=h.root_id and e.sequence=h.sequence
 left join clued_control.successor_binding s on s.root_id=h.root_id and s.generation_id=h.generation_id
 left join clued_control.execution_events se on se.root_id=h.root_id
   and se.request->>'operation'='SUCCESSOR_BINDING_REGISTERED'
   and se.request->'body'->>'binding_id'=s.binding_id
 where a.root_id=p_root_id
)
select jsonb_build_object(
 'root_set_id',(x.binding).root_id,
 'metadata_binding_sha256',case when x.generation_id in ('ctrgen_308a1dfc185cff633892638581e0a34c','ctrgen_48100437d24e448ba01c542ebe1290da','ctrgen_c725e90a595c00a041754ede3b00f408','ctrgen_1cf79ef9a7ccc37800e8837ac8c10287')
   then x.successor_binding_sha256 else encode(sha256(convert_to(to_jsonb(x.binding)::text,'UTF8')),'hex') end,
 'state',case
   when x.generation_id='ctrgen_1cf79ef9a7ccc37800e8837ac8c10287'
        and x.sequence=12
        and x.successor_binding_id='sb_6aba4e3f3b33cabcb1171e10c70f40d2'
        and x.successor_registration_sequence=139
        and x.successor_not_before='2026-09-16T07:00:00Z'::timestamptz
        and x.successor_expires_at='2026-09-23T07:00:00Z'::timestamptz
        and x.generation_body->>'control_trust_root_generation'='ctrgen_1cf79ef9a7ccc37800e8837ac8c10287'
        and (x.generation_body->>'not_before')::timestamptz='2026-09-16T07:00:00Z'::timestamptz
        and (x.generation_body->>'expires_at')::timestamptz='2026-09-23T07:00:00Z'::timestamptz then
     case when statement_timestamp()<'2026-09-16T07:00:00Z'::timestamptz or statement_timestamp()>='2026-09-23T07:00:00Z'::timestamptz
          then 'EXPIRED_OR_NOT_YET_VALID' when coalesce(x.revoked,false) then 'REVOKED' else 'STORED_NO_GATE_AUTHORITY' end
   when x.generation_id='ctrgen_1cf79ef9a7ccc37800e8837ac8c10287' then 'EXPIRED_OR_NOT_YET_VALID'
   when x.generation_id='ctrgen_c725e90a595c00a041754ede3b00f408'
        and x.sequence=11
        and x.successor_binding_id='sb_873f7cf2f79fb3cb168138441e6fddbc'
        and x.successor_registration_sequence=132
        and x.successor_not_before='2026-09-16T04:00:00Z'::timestamptz
        and x.successor_expires_at='2026-09-23T04:00:00Z'::timestamptz
        and x.generation_body->>'control_trust_root_generation'='ctrgen_c725e90a595c00a041754ede3b00f408'
        and (x.generation_body->>'not_before')::timestamptz='2026-09-16T04:00:00Z'::timestamptz
        and (x.generation_body->>'expires_at')::timestamptz='2026-09-23T04:00:00Z'::timestamptz then
     case when statement_timestamp()<'2026-09-16T04:00:00Z'::timestamptz or statement_timestamp()>='2026-09-23T04:00:00Z'::timestamptz
          then 'EXPIRED_OR_NOT_YET_VALID' when coalesce(x.revoked,false) then 'REVOKED' else 'STORED_NO_GATE_AUTHORITY' end
   when x.generation_id='ctrgen_c725e90a595c00a041754ede3b00f408' then 'EXPIRED_OR_NOT_YET_VALID'
   when x.generation_id='ctrgen_48100437d24e448ba01c542ebe1290da'
        and x.sequence=10
        and x.successor_binding_id='sb_a39581761f6a4acba5d6216279ef5e88'
        and x.successor_registration_sequence=113
        and x.successor_not_before='2026-09-15T03:00:00Z'::timestamptz
        and x.successor_expires_at='2026-09-16T03:00:00Z'::timestamptz
        and x.generation_body->>'control_trust_root_generation'='ctrgen_48100437d24e448ba01c542ebe1290da'
        and (x.generation_body->>'not_before')::timestamptz='2026-09-15T03:00:00Z'::timestamptz
        and (x.generation_body->>'expires_at')::timestamptz='2026-09-16T03:00:00Z'::timestamptz then
     case when statement_timestamp()<'2026-09-15T03:00:00Z'::timestamptz or statement_timestamp()>='2026-09-16T03:00:00Z'::timestamptz
          then 'EXPIRED_OR_NOT_YET_VALID' when coalesce(x.revoked,false) then 'REVOKED' else 'STORED_NO_GATE_AUTHORITY' end
   when x.generation_id='ctrgen_48100437d24e448ba01c542ebe1290da' then 'EXPIRED_OR_NOT_YET_VALID'
   when x.generation_id='ctrgen_308a1dfc185cff633892638581e0a34c'
        and x.sequence=9
        and x.successor_binding_id='sb_201178b7a8111000d515f7f26a75a28b'
        and x.successor_registration_sequence=98
        and x.successor_not_before='2026-09-14T03:00:00Z'::timestamptz
        and x.successor_expires_at='2026-09-15T03:00:00Z'::timestamptz
        and x.generation_body->>'control_trust_root_generation'='ctrgen_308a1dfc185cff633892638581e0a34c'
        and (x.generation_body->>'not_before')::timestamptz='2026-09-14T03:00:00Z'::timestamptz
        and (x.generation_body->>'expires_at')::timestamptz='2026-09-15T03:00:00Z'::timestamptz then
     case when statement_timestamp()<'2026-09-14T03:00:00Z'::timestamptz
                or statement_timestamp()>='2026-09-15T03:00:00Z'::timestamptz
           then 'EXPIRED_OR_NOT_YET_VALID'
          when coalesce(x.revoked,false) then 'REVOKED' else 'STORED_NO_GATE_AUTHORITY' end
   when x.generation_id='ctrgen_308a1dfc185cff633892638581e0a34c'
     then 'EXPIRED_OR_NOT_YET_VALID'
   when statement_timestamp()<(x.binding).not_before or statement_timestamp()>=(x.binding).expires_at
     then 'EXPIRED_OR_NOT_YET_VALID'
   when coalesce(x.revoked,false) then 'REVOKED' else 'STORED_NO_GATE_AUTHORITY' end,
 'sequence',coalesce(x.sequence,0),'generation_id',x.generation_id,
 'events',coalesce((select jsonb_agg(to_jsonb(e) order by e.sequence)
                    from clued_control.events e where e.root_id=(x.binding).root_id),'[]'::jsonb),
 'authority_effect','NONE')
from x
$function$;
CREATE OR REPLACE FUNCTION clued_control.reserve_execution_budget(p_raw text, p_sha text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' SET "TimeZone" TO 'UTC'
AS $function$
declare
 root constant text:='ctr_414bd3c724264a83894b0c55cf2ab878'; v jsonb; c clued_control.execution_current; b clued_control.execution_binding; w record;
 previous clued_control.execution_events; next_sequence bigint; ref jsonb; r jsonb;
begin
 if p_raw is null or p_raw is distinct from '{"controller_digest":"37fcee123e2ef063608ef13d1564cec7923c6383ec0066f41180be51ab154d56","credential_generation":"credgen_bac92a11e7144a3fb9e67f40a6a07d11","environment":"ISOLATED_TEST","evidence_bytes":134217728,"expires_at":"2026-09-23T07:00:00Z","idempotency_key":"root12_single_window_budget_20260916","not_before":"2026-09-16T07:00:00Z","profile_digest":"d1c060b85f0b842a397a478105ea57a208e62eb0a5a2d4c2cd8f93f63eae88f5","purpose":"SKILL_COEXISTENCE_QUALIFICATION","root_generation":"ctrgen_1cf79ef9a7ccc37800e8837ac8c10287","runner_generation":"runnergen_a256855fec9441839105c69b746c5244","scope_digest":"115408c69dcb2fa606fb0de34ec86c5239487d0cfa9a73abb267664a2482abe5","seconds":600,"session_generation":"sessiongen_ffb02a907d334b0da0b37bf457a758c2"}
' or p_sha is distinct from 'a49ad448c0df13b8a20f9e366ee449694f0ddaa3211633019441932d00d56714'
 or p_sha is distinct from encode(sha256(convert_to(p_raw,'UTF8')),'hex') or not(p_raw is json object with unique keys)
 then raise exception 'root10_exact_one_budget_bytes_required'; end if;
 v:=p_raw::jsonb;
 perform 1 from clued_control.current_head where root_id=root for share;
 select * into c from clued_control.execution_current where root_id=root for update;
 select * into previous from clued_control.execution_events where root_id=root and idempotency_key='root12_single_window_budget_20260916';
 if found then
  if previous.sequence<>143 or previous.request is distinct from jsonb_build_object('operation','BUDGET_RESERVED','body',jsonb_build_object('raw',p_raw,'sha256',p_sha)) then raise exception 'root10_budget_idempotency_conflict'; end if;
  return jsonb_build_object('status','DUPLICATE','event',to_jsonb(previous),'authority_effect','NONE');
 end if;
 select * into b from clued_control.effective_execution_binding(); select * into w from clued_control.effective_execution_window() where root_id=root;
 r:=clued_control.read_root(root);
 if c.sequence<>142 or c.active_ga_id is not null or c.pending_budget_sequence is not null
 or c.charged_seconds<>12306 or c.charged_evidence_bytes<>2738465715
 or r->>'state'<>'STORED_NO_GATE_AUTHORITY' or r->>'generation_id'<>'ctrgen_1cf79ef9a7ccc37800e8837ac8c10287'
 or w.generation_id<>'ctrgen_1cf79ef9a7ccc37800e8837ac8c10287' or w.budget_sequence_floor<>143
 or b.controller_sha256<>'37fcee123e2ef063608ef13d1564cec7923c6383ec0066f41180be51ab154d56' or b.qualification_sha256<>'4ffe769f19787abff6d9a1e2f1f2b16a430333bba0138f031de87a903381b317' or b.runtime_acceptance_sha256<>'7b3e08e24897e0e5fa012af68db3c4446c788231f9f94866286433c95182c861'
 or b.profile_sha256<>'d1c060b85f0b842a397a478105ea57a208e62eb0a5a2d4c2cd8f93f63eae88f5' or b.scope_sha256<>'115408c69dcb2fa606fb0de34ec86c5239487d0cfa9a73abb267664a2482abe5' or b.gate_sha256<>'3487d9fc6ccee5478569021961eac93bf5ef6bd4bc2428559b20a44abb9c155a'
 or (select count(*) from clued_control.events where root_id=root)<>12
 or (select count(*) from clued_control.execution_events where root_id=root)<>142
 or (select count(*) from clued_control.gate_attempts where root_id=root)<>18
 or exists(select 1 from clued_control.gate_attempts where root_id=root and phase not in ('FAIL','BLOCKED','STALE'))
 or (select count(*) from clued_control.execution_events where root_id=root and sequence>44 and request->>'operation'='BUDGET_RESERVED')<>12
 or (select count(*) from clued_control.execution_events where root_id=root and sequence>44 and request->>'operation'='EXECUTION_BINDING_FORWARD_ACCEPTED')<>17
 or not exists(select 1 from clued_control.gate_attempts where root_id=root and ga_id='ga_6addc4f9764b69ba8c10d258135ae0d4' and ga_sha256='327bb92ca8a27f8e67eac06daaa27afa5df99814823fe0a2eb69b7c41747641a' and phase='BLOCKED' and budget_sequence=102 and container_id is null and receipt_sha256='3d6fc55e6d2065fb40974161f3c0abb556817989c560e3072a080bea033ccfdd')
 or exists(select 1 from clued_control.execution_events where root_id=root and sequence=143)
 or clock_timestamp()<'2026-09-16T07:00:00Z'::timestamptz or clock_timestamp()+interval '600 seconds'>='2026-09-23T07:00:00Z'::timestamptz
 then raise exception 'root10_exact_prebudget_postimage_required'; end if;
 next_sequence:=c.sequence+1;
 insert into clued_control.execution_events(root_id,sequence,idempotency_key,request)
 values(root,next_sequence,'root12_single_window_budget_20260916',jsonb_build_object('operation','BUDGET_RESERVED','body',jsonb_build_object('raw',p_raw,'sha256',p_sha)));
 update clued_control.execution_current set sequence=next_sequence,pending_budget_sequence=next_sequence,
 charged_seconds=charged_seconds+600,charged_evidence_bytes=charged_evidence_bytes+134217728
 where root_id=root and sequence=142 and active_ga_id is null and pending_budget_sequence is null
 and charged_seconds=12306 and charged_evidence_bytes=2738465715;
 if not found then raise exception 'root10_budget_final_cas'; end if;
 ref:=jsonb_build_object('uri','urn:clued:control-evidence:uscrdifznmlvczcekqpw:execution-events:'||next_sequence,'sha256',p_sha);
 return jsonb_build_object('status','BUDGET_RESERVED','budget_reservation_ref',ref,'sequence',next_sequence,'authority_effect','NONE','automatic_refund',false);
end $function$;
CREATE OR REPLACE FUNCTION clued_control.reserve_gate(p_raw text, p_sha text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' SET "TimeZone" TO 'UTC'
AS $function$
declare
 root constant text:='ctr_414bd3c724264a83894b0c55cf2ab878'; gen constant text:='ctrgen_1cf79ef9a7ccc37800e8837ac8c10287';
 b clued_control.execution_binding; w record; c clued_control.execution_current; old clued_control.gate_attempts;
 r jsonb; g jsonb; series_view jsonb; series_old jsonb;
 fixed_ga jsonb:=convert_from(decode('','base64'),'UTF8')::jsonb;
 fixed_root jsonb:=convert_from(decode('','base64'),'UTF8')::jsonb;
 fixed_registered_event jsonb:=convert_from(decode('','base64'),'UTF8')::jsonb;
 fixed_prepared_event jsonb:=convert_from(decode('','base64'),'UTF8')::jsonb;
 fixed_qualified_event jsonb:=convert_from(decode('','base64'),'UTF8')::jsonb;
 start_time timestamptz; end_time timestamptz; budget clued_control.execution_events; allocation jsonb;
begin
 if p_raw is null or octet_length(p_raw)>65536 or p_sha is distinct from encode(sha256(convert_to(p_raw,'UTF8')),'hex') then raise exception 'invalid_exact_ga_bytes'; end if;
 if not (p_raw is json object with unique keys) then raise exception 'invalid_unique_ga_object'; end if;
 g:=p_raw::jsonb;
 if jsonb_typeof(g)<>'object' or coalesce(g->>'gate_authorization_id','') !~ '^ga_[A-Za-z0-9_.-]{1,128}$'
 or coalesce(g->>'idempotency_key','') !~ '^[A-Za-z0-9_-]{1,128}$' then raise exception 'invalid_ga_identity'; end if;
 perform 1 from clued_control.current_head where root_id=root for share;
 select * into c from clued_control.execution_current where root_id=root for update;
 select * into b from clued_control.effective_execution_binding(); select * into w from clued_control.effective_execution_window() where root_id=root;
 if b.root_id is null or c.root_id is null then raise exception 'accepted_execution_binding_missing'; end if;
 select * into old from clued_control.gate_attempts where root_id=root and idempotency_key=g->>'idempotency_key';
 if found then
  if old.ga_raw is distinct from p_raw or old.ga_sha256 is distinct from p_sha then raise exception 'idempotency_conflict'; end if;
  return jsonb_build_object('status','DUPLICATE','attempt',to_jsonb(old),'authority_effect','NONE');
 end if;
 -- Retain the predecessor's immutable-prefix checks. Root10 adds one exact
 -- registration event; it does not rewrite any Root9 or earlier history.
