      and e->'request'->'body'->>'control_trust_root_generation'='ctrgen_308a1dfc185cff633892638581e0a34c'
      and e->'request'->'body'->'predecessor'->>'generation_id'='ctrgen_b060bc520329398936e461af6a477f94'
