      and e->'request'->>'generation_id'='ctrgen_48100437d24e448ba01c542ebe1290da' and e->'request'->>'predecessor_generation_id'='ctrgen_308a1dfc185cff633892638581e0a34c'
      and e->'request'->>'idempotency_key'='root10_single_window_activation_20260915_root'
