      and e->'request'->'body'->'history'->>'prefix_digest'='cc08775938519ad1ecbc1e956c7314cd9c07b7230dd9392309c27c6d05d830e8')
 or encode(sha256(convert_to((select jsonb_agg(e order by (e->>'sequence')::bigint)
      from jsonb_array_elements(series_view->'root'->'events') e where (e->>'sequence')::bigint<=10)::text,'UTF8')),'hex')
      is distinct from 'ad34a824c8654830773d794042bb64d62ccec738ec22b005b6e43a56c4705184'
 or not exists(select 1 from jsonb_array_elements(series_view->'root'->'events') e
      where (e->>'sequence')::bigint=11 and e->'request'->>'kind'='GENERATION_REGISTERED'
      and e->'request'->>'root_set_id'=root and e->'request'->>'expected_sequence'='10'
      and e->'request'->>'generation_id'='ctrgen_c725e90a595c00a041754ede3b00f408' and e->'request'->>'predecessor_generation_id'='ctrgen_48100437d24e448ba01c542ebe1290da'
