      and e->'request'->>'generation_id'=gen and e->'request'->>'predecessor_generation_id'='ctrgen_c725e90a595c00a041754ede3b00f408'
      and e->'request'->>'idempotency_key'='root12_single_window_activation_20260916_root'
      and e->'request'->>'metadata_binding_sha256'='fb06ea5af1d3e34aed7a95d593f2520e83e9abb3271c30cf2f87a26232d5aa5f'
